import React, { useState, useEffect, useCallback } from 'react';
import { Box, CircularProgress } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import LeftMenu from '../components/Layout/LeftMenu';
import RightPanel from '../components/Layout/RightPanel';
import Header from '../components/Layout/Header';
import PublicationCard from '../components/Publications/PublicationCard';
import { publicationService } from '../services/publicationService';
import { Publication } from '../types';

interface Utilisateur {
    id: number;
    pseudo: string;
    email: string;
    photo_profil: string | null;
}

const Profil: React.FC = () => {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [utilisateur, setUtilisateur] = useState<Utilisateur | null>(null);
    const [publications, setPublications] = useState<Publication[]>([]);
    const [activeView, setActiveView] = useState<'actualites' | 'mes_publications'>('actualites');

    // Charger l'utilisateur depuis sessionStorage
    useEffect(() => {
        const storedUser = sessionStorage.getItem('utilisateur');
        if (!storedUser) {
            navigate('/login');
            return;
        }
        
        setUtilisateur(JSON.parse(storedUser));
        setLoading(false);
    }, [navigate]);

    // Fonction loadPublications avec useCallback pour éviter les re-créations
    const loadPublications = useCallback(async () => {
        if (!utilisateur) return;
        
        setLoading(true);
        try {
            const response = activeView === 'actualites'
                ? await publicationService.getAll()
                : await publicationService.getUserPublications(utilisateur.id);
            setPublications(response.data);
        } catch (error) {
            console.error('Erreur lors du chargement des publications', error);
        } finally {
            setLoading(false);
        }
    }, [activeView, utilisateur]); 
    
    useEffect(() => {
        if (utilisateur) {
            loadPublications();
        }
    }, [utilisateur, activeView, loadPublications]);

    const handlePublicationCreated = () => {
        loadPublications();
    };

    if (loading || !utilisateur) {
        return (
            <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
                <CircularProgress sx={{ color: '#773399' }} />
            </Box>
        );
    }

    return (
        <Box sx={{ 
            display: 'flex', 
            width: '100%', 
            minHeight: '100vh', 
            background: '#f0f2f5',
            margin: 0,
            padding: 0
        }}>
            <LeftMenu
                utilisateur={utilisateur}
                activeView={activeView}
                onViewChange={setActiveView}
            />

            <Box sx={{ 
                flex: 1, 
                display: 'flex', 
                flexDirection: 'column', 
                overflow: 'hidden', 
                minHeight: '100vh', 
                bgcolor: '#ffffff' 
            }}>
                <Header title={activeView === 'actualites' ? 'Actualités' : 'Mes publications'} />

                <Box sx={{ 
                    flex: 1, 
                    overflowY: 'auto', 
                    padding: '10px 20px', 
                    display: 'flex', 
                    flexDirection: 'column', 
                    gap: 2 
                }}>
                    {publications.length === 0 ? (
                        <Box textAlign="center" py={4} color="#999">
                            {activeView === 'actualites' ? 'Aucune publication' : 'Vous n\'avez pas encore de publications'}
                        </Box>
                    ) : (
                        publications.map((pub) => (
                            <PublicationCard
                                key={pub.id}
                                publication={pub}
                                currentUserId={utilisateur.id}
                            />
                        ))
                    )}
                </Box>
            </Box>

            <RightPanel userId={utilisateur.id} onPublicationCreated={handlePublicationCreated} />
        </Box>
    );
};

export default Profil;
